import data from '../data/gabarits.json';
import type { FaceMetrics, FaceShape } from './faceMetrics';

/**
 * The frame templates of the printable kit and of the atlas (src/data/gabarits.json, generated by
 * scripts/kit.ts): facets, measured descriptors, and a picture in public/gabarits/<id>.svg.
 * They are shapes to learn from and to try, not products: products come from the merchants.
 */

export type Mood = 'confiant' | 'créatif' | 'intellectuel' | 'professionnel' | 'glamour' | 'décontracté';

export interface Descriptor {
  ratio: number;
  roundness: number;
  presence: number;
  top: number;
  lift: number;
}

export interface Gabarit {
  id: string;
  name: string;
  kit: boolean;
  form: string;
  family: string;
  construction: 'acetate' | 'metal' | 'browline' | 'semi' | 'rimless';
  size: 'fine' | 'standard' | 'oversize';
  era: string | null;
  mood: Mood[];
  descriptor: Descriptor;
  map: [number, number];
  /** one sentence of history, for the kit icons */
  icon?: string;
}

export const GABARITS = data.templates as unknown as Gabarit[];
export const FEATURES = data.features as (keyof Descriptor)[];

export const picture = (g: Pick<Gabarit, 'id'>) => `/gabarits/${g.id}.svg`;

export const CONSTRUCTION_LABEL: Record<Gabarit['construction'], string> = {
  acetate: 'Acétate',
  metal: 'Métal',
  browline: 'Mixte',
  semi: 'Semi-cerclée',
  rimless: 'Sans cercle',
};

export const MOODS: { id: Mood; label: string }[] = [
  { id: 'confiant', label: 'Confiant' },
  { id: 'créatif', label: 'Créatif' },
  { id: 'intellectuel', label: 'Intellectuel' },
  { id: 'professionnel', label: 'Professionnel' },
  { id: 'glamour', label: 'Glamour' },
  { id: 'décontracté', label: 'Décontracté' },
];

export const FAMILIES = Array.from(new Set(GABARITS.map((g) => g.family)));

const sd = Object.fromEntries(
  FEATURES.map((k) => {
    const xs = GABARITS.map((g) => g.descriptor[k]);
    const m = xs.reduce((s, x) => s + x, 0) / xs.length;
    return [k, Math.sqrt(xs.reduce((s, x) => s + (x - m) ** 2, 0) / (xs.length - 1)) || 1];
  })
) as Record<keyof Descriptor, number>;

/** the frame a face shape calls for, in descriptor units (same rules as the kit's guide) */
const SHAPE_TARGET: Record<FaceShape, Partial<Descriptor>> = {
  round: { roundness: 0.8, ratio: 0.68, presence: 4 },
  square: { roundness: 0.97, presence: 1.2, top: 0 },
  heart: { top: 0, lift: -0.15, presence: 1, roundness: 0.9 },
  oblong: { ratio: 0.92, presence: 5.5, top: 1 },
  oval: {},
};

export interface Match {
  gabarit: Gabarit;
  /** 0–100 */
  score: number;
  why: string[];
}

/**
 * Templates ranked for a face: distance between each template's descriptors and the frame
 * the face calls for (shape, then brows, eyes and strength of the features).
 */
export function matchFace(m: FaceMetrics, list: Gabarit[] = GABARITS): Match[] {
  const target: Partial<Descriptor> = { ...SHAPE_TARGET[m.shape] };
  const why: string[] = [];
  const f = m.features;
  if (f) {
    if (f.browThickness === 'thick') {
      target.top = 3;
      target.presence = Math.max(target.presence ?? 0, 5);
      why.push('sourcils épais : un haut marqué');
    } else if (f.browThickness === 'fine') {
      target.presence = Math.min(target.presence ?? 9, 1.5);
      why.push('sourcils fins : une monture légère');
    }
    if (f.eyeSlant === 'down') {
      target.lift = 0.75;
      why.push('yeux tombants : des coins relevés');
    }
    if (target.presence === undefined) target.presence = 1 + f.intensity * 6;
  }
  const keys = FEATURES.filter((k) => target[k] !== undefined);
  return list
    .map((g) => {
      const d2 = keys.reduce((s, k) => s + ((g.descriptor[k] - target[k]!) / sd[k]) ** 2, 0);
      const score = Math.round(100 * Math.exp(-d2 / (2 * Math.max(1, keys.length))));
      return { gabarit: g, score, why };
    })
    .sort((a, b) => b.score - a.score);
}

export interface Filters {
  family?: string | null;
  construction?: Gabarit['construction'] | null;
  mood?: Mood | null;
  /** only the 21 kit icons */
  kitOnly?: boolean;
}

export function filterGabarits(list: Gabarit[], f: Filters): Gabarit[] {
  return list.filter(
    (g) =>
      (!f.kitOnly || g.kit) &&
      (!f.family || g.family === f.family) &&
      (!f.construction || g.construction === f.construction) &&
      (!f.mood || g.mood.includes(f.mood))
  );
}
